"use client"

import * as React from "react"
import { motion, useReducedMotion, type HTMLMotionProps } from "motion/react"

import { afterglow, ringMask } from "@/lib/afterglow"
import { cn } from "@/lib/utils"

type BorderBeamProps = Omit<HTMLMotionProps<"div">, "children"> & {
  /** seconds per lap */
  duration?: number
  /** thickness of the beam in px */
  width?: number
  /** length of the fading tail, in degrees of the lap */
  tail?: number
  color?: string
  /** a color the tail passes through on its way out; by default it simply fades */
  tailColor?: string
  /** a second beam on the opposite side, in its own color */
  twin?: string
  reverse?: boolean
  /** turn it off and the beam fades out slowly, still circling, instead of vanishing */
  active?: boolean
}

function BorderBeam({
  className,
  style,
  duration = 6,
  width = 1.5,
  tail = 120,
  color = "var(--glow)",
  tailColor,
  twin,
  reverse = false,
  active = true,
  ...props
}: BorderBeamProps) {
  const reduceMotion = useReducedMotion()
  const ref = React.useRef<HTMLDivElement>(null)
  const [diagonal, setDiagonal] = React.useState(0)

  // the rotating disc must cover the box at every angle, so it spans the diagonal
  React.useEffect(() => {
    const node = ref.current
    if (!node) return
    const observer = new ResizeObserver(() =>
      setDiagonal(Math.ceil(Math.hypot(node.offsetWidth, node.offsetHeight)))
    )
    observer.observe(node)
    return () => observer.disconnect()
  }, [])

  // each beam: a bright head with a long tail fading behind it
  const head = (at: number, beam: string) =>
    `transparent ${at - tail}deg, ${
      tailColor ?? `color-mix(in oklch, ${beam} 30%, transparent)`
    } ${at - tail * 0.4}deg, ${beam} ${at - 1}deg, transparent ${at}deg`
  const stops = twin
    ? `${head(180, color)}, ${head(360, twin)}`
    : `transparent 0deg, ${head(360, color)}`
  const background = `conic-gradient(from 0deg, ${stops})`

  return (
    <motion.div
      ref={ref}
      data-slot="border-beam"
      data-state={active ? "active" : "idle"}
      aria-hidden
      className={cn(
        "pointer-events-none absolute inset-0 rounded-[inherit]",
        className
      )}
      style={style}
      initial={false}
      animate={{ opacity: active ? 1 : 0 }}
      transition={
        active
          ? { duration: 0.4, ease: "easeOut" }
          : // ease in-out, so the light holds for a beat before it lets go
            { duration: afterglow.linger * 1.6, ease: "easeInOut" }
      }
      {...props}
    >
      <div
        className="absolute inset-0 overflow-hidden rounded-[inherit]"
        style={{ ...ringMask, padding: width }}
      >
        {/* a transform-only spin, so the compositor runs it without repaints */}
        <motion.div
          className="absolute top-1/2 left-1/2"
          style={{
            width: diagonal,
            height: diagonal,
            marginLeft: -diagonal / 2,
            marginTop: -diagonal / 2,
            background,
          }}
          initial={{ rotate: 0 }}
          animate={reduceMotion ? { rotate: 45 } : { rotate: reverse ? -360 : 360 }}
          transition={
            reduceMotion
              ? { duration: 0 }
              : { duration, ease: "linear", repeat: Infinity }
          }
        />
      </div>
    </motion.div>
  )
}

export { BorderBeam, type BorderBeamProps }

import type { CSSProperties } from "react"
import type { TargetAndTransition, Transition } from "motion/react"

// shared spring presets, every component picks from these
export const springs = {
  snappy: { stiffness: 520, damping: 34, mass: 0.6 },
  soft: { stiffness: 260, damping: 26, mass: 0.8 },
  glide: { stiffness: 120, damping: 20, mass: 1 },
} as const

export type SpringName = keyof typeof springs

export function spring(name: SpringName): Transition {
  return { type: "spring", ...springs[name] }
}

// how a glow fades once its source moves away: slow, with a long tail
export const afterglow = {
  linger: 0.9,
  ease: [0.22, 1, 0.36, 1],
} as const satisfies { linger: number; ease: Transition["ease"] }

// paints only the padding ring of an element, used for glowing borders
export const ringMask: CSSProperties = {
  WebkitMask:
    "linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0)",
  WebkitMaskComposite: "xor",
  mask: "linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0)",
  maskComposite: "exclude",
}

// small icon gestures, played when a control is pressed or selected
export const iconGestures = {
  pop: { scale: [1, 1.2, 1] },
  ring: { rotate: [0, -18, 14, -9, 4, 0], scale: [1, 1.12, 1] },
  // a gear looks the same after half a turn, so it can rest there and snap back unseen
  turn: { rotate: [0, 180], scale: [1, 1.12, 1] },
  hop: { y: [0, -3, 0], scale: [1, 1.1, 1] },
  nudge: { x: [0, 2.5, 0], scale: [1, 1.1, 1] },
} satisfies Record<string, TargetAndTransition>

export type IconGesture = keyof typeof iconGestures

// leaving a gesture is instant: every gesture already ends at, or looks like, its resting pose
export const iconRest: TargetAndTransition = { scale: 1, rotate: 0, x: 0, y: 0, transition: { duration: 0 } }
